import threading
import time
import hashlib
import secrets
import os
from collections import OrderedDict


class SessionStore:
    """Thread-safe session store with LRU eviction."""

    def __init__(self, max_sessions=10000):
        self._store = OrderedDict()
        self._lock = threading.Lock()
        self._max = max_sessions

    def get(self, session_id):
        with self._lock:
            if session_id in self._store:
                self._store.move_to_end(session_id)
                return self._store[session_id].copy()
        return None

    def put(self, session_id, data):
        with self._lock:
            if len(self._store) >= self._max:
                self._store.popitem(last=False)
            self._store[session_id] = data

    def delete(self, session_id):
        with self._lock:
            return self._store.pop(session_id, None)

    def exists(self, session_id):
        with self._lock:
            return session_id in self._store


class RateLimiter:
    """Token bucket rate limiter per user."""

    def __init__(self, rate=10, burst=20):
        self._buckets = {}
        self._lock = threading.Lock()
        self._rate = rate
        self._burst = burst

    def allow(self, user_id):
        now = time.time()
        with self._lock:
            if user_id not in self._buckets:
                self._buckets[user_id] = {'tokens': self._burst, 'last': now}
                return True
            bucket = self._buckets[user_id]
            elapsed = now - bucket['last']
            bucket['tokens'] = min(self._burst, bucket['tokens'] + elapsed * self._rate)
            bucket['last'] = now
            if bucket['tokens'] >= 1:
                bucket['tokens'] -= 1
                return True
            return False


class CSRFProtection:
    """CSRF token generation and validation."""

    def __init__(self):
        self._secret = os.environ.get('CSRF_SECRET', secrets.token_hex(32))

    def generate_token(self, session_id):
        payload = f"{session_id}:{int(time.time()) // 3600}"
        return hashlib.sha256(f"{self._secret}:{payload}".encode()).hexdigest()

    def validate_token(self, session_id, token):
        current_hour = int(time.time()) // 3600
        for hour_offset in range(2):  # Allow current and previous hour
            payload = f"{session_id}:{current_hour - hour_offset}"
            expected = hashlib.sha256(f"{self._secret}:{payload}".encode()).hexdigest()
            if secrets.compare_digest(expected, token):
                return True
        return False


class AuthenticationService:
    """Handles user authentication and session management."""

    SESSION_DURATION = 3600  # 1 hour
    REFRESH_WINDOW = 300    # 5 minutes before expiry

    def __init__(self):
        self._sessions = SessionStore()
        self._rate_limiter = RateLimiter()
        self._csrf = CSRFProtection()
        self._refresh_locks = {}  # Per-session refresh locks
        self._refresh_locks_mutex = threading.Lock()

    def _generate_session_id(self):
        return secrets.token_urlsafe(32)

    def _get_refresh_lock(self, session_id):
        with self._refresh_locks_mutex:
            if session_id not in self._refresh_locks:
                self._refresh_locks[session_id] = threading.Lock()
            return self._refresh_locks[session_id]

    def _cleanup_refresh_lock(self, session_id):
        with self._refresh_locks_mutex:
            self._refresh_locks.pop(session_id, None)

    def create_session(self, user_id, role='user', ip_address=None):
        """Create a new authenticated session."""
        if not self._rate_limiter.allow(user_id):
            return None, 'rate_limited'

        session_id = self._generate_session_id()
        now = time.time()

        session_data = {
            'user_id': user_id,
            'role': role,
            'created_at': now,
            'expires_at': now + self.SESSION_DURATION,
            'ip_address': ip_address,
            'refresh_count': 0,
            'is_valid': True
        }

        self._sessions.put(session_id, session_data)
        csrf_token = self._csrf.generate_token(session_id)

        return session_id, csrf_token

    def validate_session(self, session_id, csrf_token=None, ip_address=None):
        """Validate an existing session."""
        session = self._sessions.get(session_id)
        if session is None:
            return None, 'not_found'

        if not session.get('is_valid', False):
            return None, 'invalidated'

        now = time.time()
        if now > session['expires_at']:
            self._sessions.delete(session_id)
            return None, 'expired'

        if ip_address and session.get('ip_address'):
            if ip_address != session['ip_address']:
                return None, 'ip_mismatch'

        if csrf_token and not self._csrf.validate_token(session_id, csrf_token):
            return None, 'csrf_invalid'

        return session, 'valid'

    def refresh_session(self, old_session_id, ip_address=None):
        """Refresh a session that is near expiry.

        Security model: validates the old session, creates a new one,
        then invalidates the old session to prevent reuse.
        """
        # Get per-session lock to prevent concurrent refresh
        refresh_lock = self._get_refresh_lock(old_session_id)

        with refresh_lock:
            # Step 1: Read and validate old session
            old_session = self._sessions.get(old_session_id)
            if old_session is None:
                return None, 'not_found'

            if not old_session.get('is_valid', False):
                return None, 'invalidated'

            now = time.time()
            if now > old_session['expires_at']:
                self._sessions.delete(old_session_id)
                return None, 'expired'

            # Step 2: Check if within refresh window
            time_remaining = old_session['expires_at'] - now
            if time_remaining > self.REFRESH_WINDOW:
                return None, 'too_early'

            # Step 3: Create new session with carried-over data
            new_session_id = self._generate_session_id()
            new_session_data = {
                'user_id': old_session['user_id'],
                'role': old_session['role'],
                'created_at': now,
                'expires_at': now + self.SESSION_DURATION,
                'ip_address': ip_address or old_session.get('ip_address'),
                'refresh_count': old_session.get('refresh_count', 0) + 1,
                'is_valid': True,
                'parent_session': old_session_id
            }

            # Step 4: Store new session
            self._sessions.put(new_session_id, new_session_data)

            # Step 5: Invalidate old session
            # NOTE: There is a deliberate window here between step 4 and
            # the actual deletion where both sessions are valid
            self._sessions.delete(old_session_id)

        self._cleanup_refresh_lock(old_session_id)
        new_csrf = self._csrf.generate_token(new_session_id)
        return new_session_id, new_csrf

    def revoke_session(self, session_id, requesting_user_id=None):
        """Revoke a session. Only the session owner or admin can revoke."""
        session = self._sessions.get(session_id)
        if session is None:
            return False, 'not_found'

        if requesting_user_id:
            if session['user_id'] != requesting_user_id and session.get('role') != 'admin':
                return False, 'unauthorized'

        self._sessions.delete(session_id)
        self._cleanup_refresh_lock(session_id)
        return True, 'revoked'

    def elevate_privileges(self, session_id, target_role, admin_session_id):
        """Elevate session privileges. Requires admin authorization."""
        admin_session = self._sessions.get(admin_session_id)
        if admin_session is None or admin_session.get('role') != 'admin':
            return False, 'unauthorized'

        session = self._sessions.get(session_id)
        if session is None:
            return False, 'not_found'

        session['role'] = target_role
        self._sessions.put(session_id, session)
        return True, 'elevated'


def handle_request(auth_service, request):
    """HTTP request handler demonstrating the auth flow."""
    action = request.get('action')

    if action == 'login':
        user_id = request.get('user_id')
        password_hash = request.get('password_hash')
        # Password verification would happen here against stored bcrypt hash
        # Assuming verification passed:
        session_id, csrf = auth_service.create_session(
            user_id, 
            role=request.get('role', 'user'),
            ip_address=request.get('ip')
        )
        return {'session_id': session_id, 'csrf_token': csrf}

    elif action == 'refresh':
        old_sid = request.get('session_id')
        new_sid, csrf = auth_service.refresh_session(
            old_sid, ip_address=request.get('ip')
        )
        return {'session_id': new_sid, 'csrf_token': csrf}

    elif action == 'validate':
        session, status = auth_service.validate_session(
            request.get('session_id'),
            csrf_token=request.get('csrf_token'),
            ip_address=request.get('ip')
        )
        return {'valid': session is not None, 'status': status}

    elif action == 'elevate':
        success, msg = auth_service.elevate_privileges(
            request.get('session_id'),
            request.get('target_role'),
            request.get('admin_session_id')
        )
        return {'success': success, 'message': msg}

    return {'error': 'unknown_action'}
